insert into public.integration_ranking (rank,name,subtitle,category,why,effort,payer,customer_work,tier,guide_slug,platform_status,comment,scope) values
(1,'Duett hovedbok','Live','Regnskap','Inntekt og kostnad per konto. Hele lønnsomhetsregnestykket hviler på denne. Allerede i drift.','S','Kunde','Lett',1,'duett','Live – økonomirapportene er komplette, sist synkronisert 24.11, 8 biler koblet til regnskapet.',null,'plattform'),
(2,'Duett lønn','Live','Lønn','Største variable kostnad i bransjen. Uten den finnes ingen sjåførlønnsomhet. Allerede i drift.','S','Kunde','Lett',1,'lonn','Lønn kommer inn som regnskapslinjer fra Duett (én sum per måned), ikke som lønn per sjåfør.','Listen sier «Live», men Bug Tracker har «Duett Payroll integration missing», og plattformen viser bare lønn som én sum per måned. Avklar med Raman hva som faktisk er live.','plattform'),
(3,'IDHA timer','Live','Timer','Registrerte timer. Avstemmingen av timer mot lønn er selve produktet, ikke en funksjon i det.','S','Kunde','Lett',1,'idha','Ikke synlig i plattformen. Fartsskriver tar bare manuell .ddd-opplasting.','Listen og gjennomgangen sier «i drift», men det vises ingen IDOnline/IDHA-kobling i plattformen. Raman må bekrefte.','plattform'),
(4,'Scania Data Access','Under arbeid','Kjøretøy','Km, forbruk, posisjon og kjøretid. Fullfør denne — og flytt den vekk fra pilotkundens innlogging — før noe nytt startes.','M','Kunde','Lett',1,'scania','Live – 8 Scania-biler med kilometerstand og motortimer. Plattformen viser ikke om det går via kundens personlige innlogging.','Gjennomgangen sier «Koblet til» (midlertidig via O Myrens innlogging). Konkurranseklausulen i Scanias API-vilkår og EU Data Act (EØS) mangler i begrunnelsen.','plattform'),
(5,'Statens vegvesen Autosys','Kjøretøyopplysninger','Register','Tekniske data på regnummer, gratis, 50 000 kall/dag. Den eneste på listen som gir verdi FØR kunden har sagt ja: fyll en hel flåte i et salgsmøte.','S','Gratis','Ingen',1,'vegvesen','Ikke funnet i plattformen.',null,'plattform'),
(6,'Brønnøysund Enhetsregisteret',null,'Register','Org.nr., navn, adresse og roller. Gratis og trivielt. Fjerner skrivefeil i kundedata og gjør alt annet lettere å koble.','S','Gratis','Ingen',1,'brreg','Ikke funnet i plattformen.',null,'plattform'),
(7,'Brønnøysund Regnskapsregisteret',null,'Register','Offentlige årsregnskap for alle norske transportører. Lar Insiqt vise kunden hans margin mot bransjen. Gratis, og det nærmeste et datafortrinn du kommer uten kundedata.','M','Gratis','Ingen',2,'brreg','Ikke funnet i plattformen.',null,'plattform'),
(8,'Tripletex',null,'Regnskap','Stor installert base i norsk SMB. Reduserer Duett-konsentrasjonen, som i dag er den største tekniske enkeltrisikoen dere har.','M','Kunde','Lett',2,'tripletex','Ikke funnet i plattformen.',null,'plattform'),
(9,'PowerOffice Go',null,'Regnskap','Samme begrunnelse som Tripletex. Velg én av de to først — hvilken avgjøres av hva pilotkundene og de neste ti prospektene faktisk bruker.','M','Kunde','Lett',2,'poweroffice','Ikke funnet i plattformen.',null,'plattform'),
(10,'Volvo Trucks Data Access',null,'Kjøretøy','Nest største lastebilmerke i Norge. Egen forespørselsflyt via Volvo Group, og bare 14 dagers rullerende datavindu — Insiqt må lagre selv.','L','Kunde','Lett',2,'volvo','Kode finnes (/volvo), ikke koblet til. Siden viser «No organization found for this user».','Gjennomgangen: Volvo og Renault må avklares skriftlig mot EU Data Act – Insiqt er etablert i EØS, ikke EU.','plattform'),
(11,'Renault Trucks',null,'Kjøretøy','Samme konsern som Volvo og samme Data Act-flyt. Bygg rett etter Volvo og sjekk om adapteren kan deles. To merker for nær én innsats.','M','Kunde','Lett',2,null,'Ikke funnet i plattformen.','Gjennomgangen sier Renault krever at tredjeparten er etablert i EU. Insiqt er i EØS. Avklar før dette bygges.','plattform'),
(12,'Bompenger — AutoSync / SkyttelPASS / Flyt','AutoPASS-utstedere','Kostnad','Reell kostnad per tur i Norge som nesten ingen fordeler riktig manuelt. Hvilken leverandør avhenger av kundens avtale — spør før du velger.','M','Kunde','Lett',2,'bom','Kode for AutoSync finnes (/autosync), ikke koblet til – krever bedriftsavtale med AutoSync.','Gjennomgangen prioriterer bompenger nå. Spør pilotkundene hvilken leverandør de bruker.','plattform'),
(13,'Duett: timebærende lønnsart','Felt, ikke integrasjon','Lønn','Det ene feltet som får timeavstemmingen til å stemme. Høyest verdi per utviklingstime av alt på hele listen, og det er ikke engang en integrasjon.','S','Gratis','Ingen',2,'duett','Ikke på plass – timer stemmer ikke med lønn ennå.','Teksten sier «høyest verdi per utviklingstime av alt på hele listen», men den står som nr. 13 på nivå 2. Gjennomgangen gjør den til hovedprioritet. Bør flyttes til nivå 1.','plattform'),
(14,'Visma eAccounting / Business',null,'Regnskap','Stor base, særlig hos litt større transportører. Tyngre API enn Tripletex, derfor bak den.','L','Kunde','Lett',2,null,null,null,'plattform'),
(15,'Fiken',null,'Regnskap','Mange av de minste selskapene. Lav verdi per kunde, men også lav innsats — tas når en kunde ber om det.','S','Kunde','Lett',2,null,null,null,'plattform'),
(16,'Altinn / A-melding',null,'Register','Innrapporterte lønns- og timedata. Kan validere avstemmingen mot det som faktisk er rapportert til staten. Tung autentisering via Maskinporten.','L','Gratis','Tung',2,null,'Ikke funnet i plattformen.',null,'plattform'),
(17,'MAN RIO',null,'Kjøretøy','Tredje store merke. Går via RIO-plattformen, ikke et rent API — kunden må ha RIO-konto, så onboardingen er en annen enn Scanias.','L','Kunde','Lett',3,'rfms-andre','Ikke funnet i plattformen.',null,'plattform'),
(18,'DAF Connect',null,'Kjøretøy','DAF Connect Open Platform åpner for «trusted third-party suppliers» i rFMS-format, men det krever å bli godkjent. Blokkert på en samtale, ikke på kode.','L','Ukjent','Lett',3,'rfms-andre','Ikke funnet i plattformen.',null,'plattform'),
(19,'Mercedes / Daimler Truck',null,'Kjøretøy','Fleet Partner API krever signert rammeavtale, og Fleetboard har SOAP. Vanskeligste av alle produsentene — start dialogen tidlig, bygg sent.','L','Ukjent','Lett',3,'daimler','Ikke funnet i plattformen.',null,'plattform'),
(20,'Oppdragsgiverportal — Bring / Posten',null,'Oppdrag','For en underleverandør kommer både oppdrag og avregning fra oppdragsgiveren, ikke fra eget system. Da ligger inntekt per tur her. Høy verdi, høy usikkerhet — valider før du bygger.','L','Ukjent','Lett',3,null,'Ikke funnet i plattformen.',null,'plattform'),
(21,'Oppdragsgiverportal — PostNord',null,'Oppdrag','Samme begrunnelse som Bring. Hvilken som gjelder avhenger helt av hvem kunden kjører for.','L','Ukjent','Lett',3,null,null,null,'plattform'),
(22,'Oppdragsgiverportal — DB Schenker',null,'Oppdrag','Samme begrunnelse. Mange norske transportører har hovedvekten av omsetningen sin hos én slik oppdragsgiver.','L','Ukjent','Lett',3,null,null,null,'plattform'),
(23,'Hogia UniTrans',null,'TMS','Ordrehåndtering, ressursplanlegging og faktureringsgrunnlag. Lang historie i Norge. Nødvendig for kunder med mange oppdrag per dag.','L','Kunde','Lett',3,null,null,null,'plattform'),
(24,'Opter',null,'TMS','Oppgir over 600 transport- og logistikkselskaper i Norden. Sterk i distribusjon og bud, der tur-lønnsomhet er umulig uten oppdragsdata.','L','Kunde','Lett',3,null,null,null,'plattform'),
(25,'Frakt24',null,'TMS','Norsk sky-TMS med ordre, disponering, ruteplan og fakturering. Moderne, og sannsynligvis lettest å integrere av TMS-ene.','M','Kunde','Lett',3,null,null,null,'plattform'),
(26,'ABAX',null,'Telematikk','Én integrasjon dekker alle merker, varebiler og maskiner. Men den krever maskinvare, har tynnere motordata enn rFMS, og koster trolig Insiqt penger per kjøretøy. Bygg bare hvis pilotkundene allerede har det.','M','Insiqt','Lett',3,'abax','Kode finnes (/abax), ikke koblet til.','Listen sier «bygg bare hvis pilotkundene har det», men tilkoblingssiden er allerede bygget. Avklar hvor ferdig den er.','plattform'),
(27,'Fartsskriver fjernnedlasting — VDO / Stoneridge',null,'Timer','Kjøre- og hviletid rett fra fartsskriveren. Alternativ eller supplement til IDHA, og juridisk sterkere kilde ved kontroll.','L','Kunde','Tung',3,'fartsskriver-andre','Fartsskriver tar bare manuell .ddd-opplasting.',null,'plattform'),
(28,'Xledger',null,'Regnskap','Norsk, brukt av litt større selskaper med flere datterselskaper. Godt API.','M','Kunde','Lett',3,null,null,null,'plattform'),
(29,'24SevenOffice',null,'Regnskap','Etablert base. Tas når en konkret kunde krever det.','M','Kunde','Lett',3,'24so','Ikke funnet i plattformen.',null,'plattform'),
(30,'Uni Micro',null,'Regnskap','Mindre, men finnes hos en del transportører. Rent etterspørselsdrevet.','M','Kunde','Lett',3,null,null,null,'plattform'),
(31,'Visma Lønn',null,'Lønn','Lønnssystemet som oftest ligger ved siden av et annet regnskapssystem. Relevant så snart dere får en kunde som ikke kjører lønn i Duett.','L','Kunde','Lett',3,null,null,null,'plattform'),
(32,'Huldt & Lillevik',null,'Lønn','Samme begrunnelse. Fortsatt utbredt i norsk SMB.','L','Kunde','Lett',3,null,null,null,'plattform'),
(33,'Tidsbanken',null,'Timer','Norsk timeregistrering med god utbredelse. Alternativ til IDHA hos kunder som ikke har IDHA.','M','Kunde','Lett',3,null,null,null,'plattform'),
(34,'Løyveregisteret (Vegvesen)',null,'Register','Transportløyve og gyldighet. Billig compliance-funksjon og en naturlig del av avvikssiden.','S','Gratis','Ingen',3,null,null,null,'plattform'),
(35,'IVECO',null,'Kjøretøy','Listet i rFMS, men verken Data Act-side eller utviklerportal funnet offentlig. Behandle som ukjent — ikke lov en IVECO-kunde noe.','L','Ukjent','Ukjent',4,'rfms-andre','Ikke funnet i plattformen.',null,'plattform'),
(36,'Nord Pool — spotpris strøm',null,'Energi','Kritisk for El-kalkulatoren. Uten spotpris er beregningen av elektrisk mot diesel gjetning. Åpne data, lav innsats, høy verdi den dagen kundene elektrifiserer.','S','Gratis','Ingen',4,null,null,null,'plattform'),
(37,'Lading — Mer',null,'Energi','kWh og kostnad per lading per kjøretøy. Blir drivstoffkortet for elektriske flåter.','M','Kunde','Lett',4,null,null,null,'plattform'),
(38,'Lading — Recharge',null,'Energi','Samme begrunnelse. Hvilken som gjelder avhenger av kundens ladeavtale.','M','Kunde','Lett',4,null,null,null,'plattform'),
(39,'Lading — Kople',null,'Energi','Samme begrunnelse.','M','Kunde','Lett',4,null,null,null,'plattform'),
(40,'Lading — Eviny',null,'Energi','Samme begrunnelse, sterkest på Vestlandet.','M','Kunde','Lett',4,null,null,null,'plattform'),
(41,'Depotlading — Zaptec',null,'Energi','Lading på egen base er der de fleste kWh faktisk tas. Norsk leverandør.','M','Kunde','Lett',4,null,null,null,'plattform'),
(42,'Depotlading — Easee',null,'Energi','Samme begrunnelse.','M','Kunde','Lett',4,null,null,null,'plattform'),
(43,'Drivstoffkort — Circle K',null,'Kostnad','Gir hvem som fylte hvor. Men kostnaden ligger allerede i Duett og forbruk per bil kommer fra rFMS, så merverdien er svinnkontroll — ikke lønnsomhet. Ingen offentlig API funnet.','M','Ukjent','Lett',4,'drivstoff-fil','Ikke i plattformen – bare innsendinger fra sjåfør (siden gir «Forbidden»).','Gjennomgangen prioriterer drivstoffkort som filimport nå, listen setter dem på nivå 4. Drivstoffkort gir forbruk og kostnad per bil, som fordeler Duett-kontoen for drivstoff på riktig bil – det er lønnsomhet per bil, ikke bare svinnkontroll. Velg én av de to vurderingene.','plattform'),
(44,'Drivstoffkort — Uno-X / YX',null,'Kostnad','Samme begrunnelse. Ingen offentlig API-dokumentasjon funnet.','M','Ukjent','Lett',4,'drivstoff-fil','Ikke i plattformen.','Se Circle K.','plattform'),
(45,'Drivstoffkort — Shell / Euroshell',null,'Kostnad','Samme begrunnelse, mer relevant for internasjonal kjøring.','M','Ukjent','Lett',4,'drivstoff-fil','Ikke i plattformen.','Se Circle K.','plattform'),
(46,'Drivstoffkort — DKV',null,'Kostnad','Paneuropeisk kort. Relevant først når kundene kjører utenfor Norden.','M','Ukjent','Lett',4,null,null,null,'plattform'),
(47,'Drivstoffkort — Eurowag',null,'Kostnad','Samme begrunnelse som DKV.','M','Ukjent','Lett',4,null,null,null,'plattform'),
(48,'Dekk — Continental ContiConnect',null,'Vedlikehold','Dekktrykk og slitasje. Dekk er en reell kostnadslinje, men sjelden den som avgjør om en kunde kjøper.','M','Kunde','Tung',4,null,null,null,'plattform'),
(49,'Dekk — Michelin',null,'Vedlikehold','Samme begrunnelse.','M','Kunde','Tung',4,null,null,null,'plattform'),
(50,'Dekk — Bridgestone / Webfleet',null,'Vedlikehold','Samme begrunnelse, og Webfleet gir også telematikk.','M','Kunde','Tung',4,null,null,null,'plattform'),
(51,'Telematikk — GSGroup / Guard Systems',null,'Telematikk','Norsk ettermontert alternativ til ABAX. Samme vurdering: bare hvis kunden allerede har det.','M','Insiqt','Lett',4,null,null,null,'plattform'),
(52,'Telematikk — Webfleet',null,'Telematikk','Stor i Europa. Relevant hvis en større kunde allerede står på den.','M','Insiqt','Lett',4,'webfleet','Ikke funnet i plattformen.',null,'plattform'),
(53,'Telematikk — Geotab',null,'Telematikk','Åpen plattform med godt API, men lite utbredt i norsk transport-SMB.','M','Insiqt','Lett',4,null,null,null,'plattform'),
(54,'Telematikk — Samsara',null,'Telematikk','Sterk plattform, men dyr og lite utbredt i Norge. Konkurrerer også delvis med Insiqt.','M','Insiqt','Lett',4,null,null,null,'plattform'),
(55,'Henger — Schmitz Cargobull',null,'Kjøretøy','Hengertelematikk: last, temperatur, dekk. Kritisk for termo, irrelevant ellers.','L','Kunde','Lett',4,null,null,null,'plattform'),
(56,'Henger — Krone',null,'Kjøretøy','Samme begrunnelse.','L','Kunde','Lett',4,null,null,null,'plattform'),
