(58,'Termo — Thermo King',null,'Kjøretøy','Temperaturlogg som dokumentasjon. Blir et krav i det øyeblikket dere tar en kunde med kjøl eller frys.','L','Kunde','Tung',4,null,null,null,'plattform'),
(59,'Termo — Carrier Transicold',null,'Kjøretøy','Samme begrunnelse.','L','Kunde','Tung',4,null,null,null,'plattform'),
(60,'Varebil — Ford Pro',null,'Kjøretøy','Best utbygde varebil-API-et. Relevant kun hvis distribusjon blir en egen vertikal.','M','Kunde','Lett',4,null,null,null,'plattform'),
(61,'Varebil — Stellantis',null,'Kjøretøy','Fiat, Peugeot, Citroën, Opel. Samme forbehold.','M','Kunde','Lett',4,null,null,null,'plattform'),
(62,'Varebil — VW Nutzfahrzeuge',null,'Kjøretøy','Samme forbehold.','M','Kunde','Lett',4,null,null,null,'plattform'),
(63,'Buss — Volvo Buses',null,'Kjøretøy','Buss er egen vertikal med egen økonomi og egne kontrakter. Ikke bygg før den vertikalen er besluttet.','L','Kunde','Lett',4,null,null,null,'plattform'),
(64,'Buss — VDL',null,'Kjøretøy','Samme begrunnelse.','L','Kunde','Lett',4,null,null,null,'plattform'),
(65,'Kart — HERE',null,'Kart','Beste lastebilruting i Europa, med vektbegrensninger og bomveier. Nødvendig først når dere faktisk beregner ruter, ikke bare viser posisjon.','M','Insiqt','Ingen',5,null,null,null,'plattform'),
(66,'Kart — Google Maps',null,'Kart','Enklest å komme i gang med, men dårligere på lastebilrestriksjoner og dyrere ved volum.','S','Insiqt','Ingen',5,null,null,null,'plattform'),
(67,'Kart — Mapbox',null,'Kart','God kartvisning til lav pris. Vurder mot HERE etter hva dere faktisk trenger: visning eller ruting.','S','Insiqt','Ingen',5,null,null,null,'plattform'),
(68,'NVDB — Vegvesen vegdata',null,'Kart','Vegnett, bruksklasser, tillatt totalvekt. Gratis norske data som Google ikke har. Interessant, men ingen etterspør det ennå.','M','Gratis','Ingen',5,null,null,null,'plattform'),
(69,'Met.no — vær',null,'Kart','Vær påvirker forbruk og forsinkelser. Gratis, men forklaringsverdien er marginal før grunnproduktet virker.','S','Gratis','Ingen',5,null,null,null,'plattform'),
