(72,'Konkursregisteret',null,'Register','Kredittrisiko på oppdragsgivere. Nyttig, men løses billigere med en kredittsjekktjeneste.','S','Gratis','Ingen',5,null,null,null,'plattform'),
(73,'Skatteetaten — MVA',null,'Register','Avstemming mot innsendte oppgaver. Tung autentisering, liten gevinst.','L','Gratis','Tung',5,null,null,null,'plattform'),
