-- Rangering av 100 integrasjoner (fra Insiqt-100-integrasjoner-rangert.html, nov 2026) og skille mellom plattform og kontrollsenter.
create table if not exists public.integration_ranking (
  rank int primary key, name text not null, subtitle text, category text, why text,
  effort text, payer text, customer_work text, tier int not null,
  guide_slug text references public.integration_guides(slug) on delete set null,
  platform_status text, comment text, scope text not null default 'plattform' check (scope in ('plattform','kontroll')),
  updated_at timestamptz default now()
);
alter table public.integration_ranking enable row level security;
drop policy if exists "ranking read" on public.integration_ranking;
create policy "ranking read" on public.integration_ranking for select to authenticated using (true);
revoke all on public.integration_ranking from anon;
grant select on public.integration_ranking to authenticated;
alter table public.integration_guides add column if not exists platform_status text;
alter table public.integration_guides add column if not exists platform_checked_at date;
on conflict (rank) do nothing;
